package pe.com.asistencia.organization.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
import pe.com.asistencia.organization.domain.*; import pe.com.asistencia.organization.repository.*; import java.util.List;
@RestController @RequestMapping("/api/v1/organization") @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')")
public class OrganizationController {
 private final SiteRepository sites; private final AreaRepository areas; private final PositionRepository positions;
 public OrganizationController(SiteRepository sites,AreaRepository areas,PositionRepository positions){this.sites=sites;this.areas=areas;this.positions=positions;}
 @GetMapping("/sites") public List<SiteView> sites(){return sites.findAll().stream().map(SiteView::of).toList();}
 @PostMapping("/sites") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public SiteView createSite(@Valid @RequestBody SiteRequest r){if(sites.existsByCodeIgnoreCase(r.code()))conflict();return SiteView.of(sites.save(new Site(r.code(),r.name(),r.address(),r.timeZone(),r.latitude(),r.longitude())));}
 @PutMapping("/sites/{id}") @PreAuthorize("hasRole('ADMIN')") public SiteView updateSite(@PathVariable Long id,@Valid @RequestBody SiteUpdate r){var e=sites.findById(id).orElseThrow(this::notFound);e.update(r.name(),r.address(),r.timeZone(),r.latitude(),r.longitude(),r.active());return SiteView.of(sites.save(e));}
 @PatchMapping("/sites/{id}/attendance-security") @PreAuthorize("hasRole('ADMIN')") public SiteView security(@PathVariable Long id,@Valid @RequestBody SiteSecurityRequest r){var e=sites.findById(id).orElseThrow(this::notFound);e.configureSecurity(r.geofenceRadiusM(),r.requireGeofence(),r.requireRegisteredDevice(),r.requireDynamicQr(),r.allowedWifiBssid(),r.requireWifi());return SiteView.of(sites.save(e));}
 @GetMapping("/areas") public List<CatalogView> areas(){return areas.findAll().stream().map(a->new CatalogView(a.getId(),a.getCode(),a.getName(),a.getDescription(),a.isActive())).toList();}
 @PostMapping("/areas") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public CatalogView createArea(@Valid @RequestBody CatalogRequest r){if(areas.existsByCodeIgnoreCase(r.code()))conflict();var a=areas.save(new Area(r.code(),r.name(),r.description()));return new CatalogView(a.getId(),a.getCode(),a.getName(),a.getDescription(),a.isActive());}
 @PutMapping("/areas/{id}") @PreAuthorize("hasRole('ADMIN')") public CatalogView updateArea(@PathVariable Long id,@Valid @RequestBody CatalogUpdate r){var a=areas.findById(id).orElseThrow(this::notFound);a.update(r.name(),r.description(),r.active());a=areas.save(a);return new CatalogView(a.getId(),a.getCode(),a.getName(),a.getDescription(),a.isActive());}
 @GetMapping("/positions") public List<CatalogView> positions(){return positions.findAll().stream().map(p->new CatalogView(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.isActive())).toList();}
 @PostMapping("/positions") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public CatalogView createPosition(@Valid @RequestBody CatalogRequest r){if(positions.existsByCodeIgnoreCase(r.code()))conflict();var p=positions.save(new Position(r.code(),r.name(),r.description()));return new CatalogView(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.isActive());}
 @PutMapping("/positions/{id}") @PreAuthorize("hasRole('ADMIN')") public CatalogView updatePosition(@PathVariable Long id,@Valid @RequestBody CatalogUpdate r){var p=positions.findById(id).orElseThrow(this::notFound);p.update(r.name(),r.description(),r.active());p=positions.save(p);return new CatalogView(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.isActive());}
 private void conflict(){throw new ResponseStatusException(HttpStatus.CONFLICT,"El código ya existe");} private ResponseStatusException notFound(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Registro no encontrado");}
 public record CatalogRequest(@NotBlank @Size(max=40) String code,@NotBlank @Size(max=150) String name,@Size(max=255) String description){} public record CatalogUpdate(@NotBlank @Size(max=150) String name,@Size(max=255) String description,boolean active){} public record CatalogView(Long id,String code,String name,String description,boolean active){}
 public record SiteRequest(@NotBlank @Size(max=40) String code,@NotBlank @Size(max=150) String name,@Size(max=255) String address,@NotBlank String timeZone,Double latitude,Double longitude){} public record SiteUpdate(@NotBlank String name,String address,@NotBlank String timeZone,Double latitude,Double longitude,boolean active){} public record SiteSecurityRequest(@Positive Integer geofenceRadiusM,boolean requireGeofence,boolean requireRegisteredDevice,boolean requireDynamicQr,@Size(max=32) String allowedWifiBssid,boolean requireWifi){} public record SiteView(Long id,String code,String name,String address,String timeZone,Double latitude,Double longitude,boolean active,Integer geofenceRadiusM,boolean requireGeofence,boolean requireRegisteredDevice,boolean requireDynamicQr,String allowedWifiBssid,boolean requireWifi){static SiteView of(Site s){return new SiteView(s.getId(),s.getCode(),s.getName(),s.getAddress(),s.getTimeZone(),s.getLatitude(),s.getLongitude(),s.isActive(),s.getGeofenceRadiusM(),s.isRequireGeofence(),s.isRequireRegisteredDevice(),s.isRequireDynamicQr(),s.getAllowedWifiBssid(),s.isRequireWifi());}}
}
